values (
  'en-super-bowl-trivia',
  'Super Bowl Trivia: History, Records and MVPs',
  'Eight questions on the Super Bowl: the first title game, the perfect season, a record comeback and the players who defined the big game.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Which team won the first Super Bowl, played in January 1967?","options":[{"id":"a","text":"Green Bay Packers","is_correct":true},{"id":"b","text":"Kansas City Chiefs","is_correct":false},{"id":"c","text":"Baltimore Colts","is_correct":false},{"id":"d","text":"Dallas Cowboys","is_correct":false}],"explanation":"Green Bay beat the Kansas City Chiefs 35-10 on 15 January 1967 at the Los Angeles Memorial Coliseum."},{"id":"q2","question":"What was the first Super Bowl officially called?","options":[{"id":"a","text":"AFL-NFL World Championship Game","is_correct":true},{"id":"b","text":"The Big Game","is_correct":false},{"id":"c","text":"NFL Championship Game","is_correct":false},{"id":"d","text":"Pro Bowl Final","is_correct":false}],"explanation":"The name ''Super Bowl'' was unofficial at first; the inaugural game was billed as the AFL-NFL World Championship Game."},{"id":"q3","question":"Who was named MVP of each of the first two Super Bowls?","options":[{"id":"a","text":"Bart Starr","is_correct":true},{"id":"b","text":"Joe Namath","is_correct":false},{"id":"c","text":"Len Dawson","is_correct":false},{"id":"d","text":"Johnny Unitas","is_correct":false}],"explanation":"Packers quarterback Bart Starr won the MVP award in Super Bowls I and II."},{"id":"q4","question":"Which player holds the record for most Super Bowl MVP awards, with five?","options":[{"id":"a","text":"Tom Brady","is_correct":true},{"id":"b","text":"Joe Montana","is_correct":false},{"id":"c","text":"Bart Starr","is_correct":false},{"id":"d","text":"Peyton Manning","is_correct":false}],"explanation":"Brady was named MVP in five of his seven Super Bowl wins; Joe Montana follows with three."},{"id":"q5","question":"Which team completed the only perfect season in NFL history with a Super Bowl win?","options":[{"id":"a","text":"Miami Dolphins","is_correct":true},{"id":"b","text":"Pittsburgh Steelers","is_correct":false},{"id":"c","text":"San Francisco 49ers","is_correct":false},{"id":"d","text":"Chicago Bears","is_correct":false}],"explanation":"The 1972 Dolphins went 17-0, capping it with a 14-7 win over Washington in Super Bowl VII."},{"id":"q6","question":"Which Jets quarterback famously guaranteed victory before Super Bowl III?","options":[{"id":"a","text":"Joe Namath","is_correct":true},{"id":"b","text":"Johnny Unitas","is_correct":false},{"id":"c","text":"Roger Staubach","is_correct":false},{"id":"d","text":"Bart Starr","is_correct":false}],"explanation":"''Broadway Joe'' Namath promised a win and delivered: the Jets upset the heavily favored Colts 16-7 in 1969."},{"id":"q7","question":"In Super Bowl LI, the Patriots rallied from a 28-3 deficit to beat which team?","options":[{"id":"a","text":"Atlanta Falcons","is_correct":true},{"id":"b","text":"Seattle Seahawks","is_correct":false},{"id":"c","text":"Los Angeles Rams","is_correct":false},{"id":"d","text":"Philadelphia Eagles","is_correct":false}],"explanation":"New England won 34-28 in overtime in February 2017 — the largest comeback in Super Bowl history."},{"id":"q8","question":"What is the name of the trophy awarded to the Super Bowl champion?","options":[{"id":"a","text":"Vince Lombardi Trophy","is_correct":true},{"id":"b","text":"Pete Rozelle Trophy","is_correct":false},{"id":"c","text":"Commissioner''s Trophy","is_correct":false},{"id":"d","text":"Lombardi Cup","is_correct":false}],"explanation":"The trophy was renamed for Vince Lombardi after his death in 1970; the Commissioner''s Trophy goes to the World Series winner."}]'::jsonb,
  null,
  array['super bowl', 'nfl', 'american football', 'championships']::text[],
  3,
  'published',
