  '[{"id":"q1","question":"¿Qué equipo ganó el primer Super Bowl, jugado en enero de 1967?","options":[{"id":"a","text":"Green Bay Packers","is_correct":true},{"id":"b","text":"Kansas City Chiefs","is_correct":false},{"id":"c","text":"Baltimore Colts","is_correct":false},{"id":"d","text":"Dallas Cowboys","is_correct":false}],"explanation":"Green Bay venció 35-10 a Kansas City el 15 de enero de 1967 en el Los Angeles Memorial Coliseum."},{"id":"q2","question":"¿Cómo se llamaba oficialmente el primer Super Bowl?","options":[{"id":"a","text":"AFL-NFL World Championship Game","is_correct":true},{"id":"b","text":"El Juego Grande","is_correct":false},{"id":"c","text":"NFL Championship Game","is_correct":false},{"id":"d","text":"Pro Bowl Final","is_correct":false}],"explanation":"El nombre ''Super Bowl'' era extraoficial al principio; el juego inaugural se anunció como AFL-NFL World Championship Game."},{"id":"q3","question":"¿Quién fue nombrado MVP en cada uno de los dos primeros Super Bowls?","options":[{"id":"a","text":"Bart Starr","is_correct":true},{"id":"b","text":"Joe Namath","is_correct":false},{"id":"c","text":"Len Dawson","is_correct":false},{"id":"d","text":"Johnny Unitas","is_correct":false}],"explanation":"Bart Starr, mariscal de campo de los Packers, ganó el premio MVP en los Super Bowls I y II."},{"id":"q4","question":"¿Qué jugador tiene el récord de más premios MVP del Super Bowl, con cinco?","options":[{"id":"a","text":"Tom Brady","is_correct":true},{"id":"b","text":"Joe Montana","is_correct":false},{"id":"c","text":"Bart Starr","is_correct":false},{"id":"d","text":"Peyton Manning","is_correct":false}],"explanation":"Brady fue MVP en cinco de sus siete títulos de Super Bowl; Joe Montana le sigue con tres."},{"id":"q5","question":"¿Qué equipo completó la única temporada perfecta de la NFL con un título de Super Bowl?","options":[{"id":"a","text":"Miami Dolphins","is_correct":true},{"id":"b","text":"Pittsburgh Steelers","is_correct":false},{"id":"c","text":"San Francisco 49ers","is_correct":false},{"id":"d","text":"Chicago Bears","is_correct":false}],"explanation":"Los Dolphins de 1972 terminaron 17-0 y cerraron con victoria 14-7 sobre Washington en el Super Bowl VII."},{"id":"q6","question":"¿Qué mariscal de campo de los Jets garantizó la victoria antes del Super Bowl III?","options":[{"id":"a","text":"Joe Namath","is_correct":true},{"id":"b","text":"Johnny Unitas","is_correct":false},{"id":"c","text":"Roger Staubach","is_correct":false},{"id":"d","text":"Bart Starr","is_correct":false}],"explanation":"''Broadway Joe'' Namath cumplió su promesa: los Jets vencieron 16-7 a los favoritos Colts en 1969."},{"id":"q7","question":"En el Super Bowl LI, los Patriots remontaron un déficit de 28-3 para vencer a qué equipo?","options":[{"id":"a","text":"Atlanta Falcons","is_correct":true},{"id":"b","text":"Seattle Seahawks","is_correct":false},{"id":"c","text":"Los Angeles Rams","is_correct":false},{"id":"d","text":"Philadelphia Eagles","is_correct":false}],"explanation":"Nueva Inglaterra ganó 34-28 en tiempo extra en febrero de 2017, la mayor remontada de la historia del Super Bowl."},{"id":"q8","question":"¿Cómo se llama el trofeo que recibe el campeón del Super Bowl?","options":[{"id":"a","text":"Trofeo Vince Lombardi","is_correct":true},{"id":"b","text":"Trofeo Pete Rozelle","is_correct":false},{"id":"c","text":"Commissioner''s Trophy","is_correct":false},{"id":"d","text":"Copa Lombardi","is_correct":false}],"explanation":"El trofeo lleva el nombre de Vince Lombardi desde su muerte en 1970; el Commissioner''s Trophy se entrega al campeón de la Serie Mundial."}]'::jsonb,
