values (
  'en-nfl-history-trivia',
  'NFL History Trivia: Founding, Teams and Legends',
  'Eight questions on the history of the National Football League: its 1920 founding, the AFL merger, historic franchises, record holders and iconic stadiums.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"In what year was the league that became the NFL founded?","options":[{"id":"a","text":"1920","is_correct":true},{"id":"b","text":"1892","is_correct":false},{"id":"c","text":"1936","is_correct":false},{"id":"d","text":"1946","is_correct":false}],"explanation":"The league was founded in 1920 in Canton, Ohio, and renamed the National Football League in 1922."},{"id":"q2","question":"What was the NFL called at its founding?","options":[{"id":"a","text":"American Professional Football Association","is_correct":true},{"id":"b","text":"National Football League","is_correct":false},{"id":"c","text":"United States Football League","is_correct":false},{"id":"d","text":"American Football League","is_correct":false}],"explanation":"It began as the American Professional Football Association and took the NFL name two years later."},{"id":"q3","question":"Which franchise has won the most NFL championships, with thirteen?","options":[{"id":"a","text":"Green Bay Packers","is_correct":true},{"id":"b","text":"Chicago Bears","is_correct":false},{"id":"c","text":"New York Giants","is_correct":false},{"id":"d","text":"Pittsburgh Steelers","is_correct":false}],"explanation":"The Packers'' thirteen titles include nine from before the Super Bowl era and four Super Bowl wins."},{"id":"q4","question":"The NFL merged with which rival league in a process completed in 1970?","options":[{"id":"a","text":"American Football League","is_correct":true},{"id":"b","text":"United States Football League","is_correct":false},{"id":"c","text":"All-America Football Conference","is_correct":false},{"id":"d","text":"XFL","is_correct":false}],"explanation":"The merger with the American Football League created today''s AFC and NFC conferences."},{"id":"q5","question":"Which is the oldest continuously operating NFL franchise, founded in 1898?","options":[{"id":"a","text":"Arizona Cardinals","is_correct":true},{"id":"b","text":"Chicago Bears","is_correct":false},{"id":"c","text":"Green Bay Packers","is_correct":false},{"id":"d","text":"New York Giants","is_correct":false}],"explanation":"The Cardinals began as Chicago''s Morgan Athletic Club in 1898, decades before the league existed."},{"id":"q6","question":"Which expansion team is the newest in the NFL, having joined in 2002?","options":[{"id":"a","text":"Houston Texans","is_correct":true},{"id":"b","text":"Jacksonville Jaguars","is_correct":false},{"id":"c","text":"Carolina Panthers","is_correct":false},{"id":"d","text":"Baltimore Ravens","is_correct":false}],"explanation":"The Texans began play in 2002; the Jaguars and Panthers arrived in 1995 and the Ravens franchise in 1996."},{"id":"q7","question":"Who is the NFL''s all-time leading rusher, with 18,355 yards?","options":[{"id":"a","text":"Emmitt Smith","is_correct":true},{"id":"b","text":"Walter Payton","is_correct":false},{"id":"c","text":"Barry Sanders","is_correct":false},{"id":"d","text":"Jim Brown","is_correct":false}],"explanation":"Smith passed Walter Payton in 2002 and retired after the 2004 season; his record still stands."},{"id":"q8","question":"What is the oldest stadium still in continuous use in the NFL?","options":[{"id":"a","text":"Lambeau Field","is_correct":true},{"id":"b","text":"Soldier Field","is_correct":false},{"id":"c","text":"Arrowhead Stadium","is_correct":false},{"id":"d","text":"AT&T Stadium","is_correct":false}],"explanation":"Lambeau Field opened in 1957 and has been the Packers'' home ever since."}]'::jsonb,
