insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-mlb-trivia',
  'MLB Trivia: History, Rules and Record Books',
  'Eight questions on Major League Baseball: the rules of the game, the oldest league, career record holders, the color barrier and famous curses.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"How many innings does a regulation Major League game last?","options":[{"id":"a","text":"Nine","is_correct":true},{"id":"b","text":"Seven","is_correct":false},{"id":"c","text":"Ten","is_correct":false},{"id":"d","text":"Twelve","is_correct":false}],"explanation":"Nine innings, unless the score is tied — extra innings continue until there is a winner."},{"id":"q2","question":"Which is the older of MLB''s two leagues, founded in 1876?","options":[{"id":"a","text":"National League","is_correct":true},{"id":"b","text":"American League","is_correct":false},{"id":"c","text":"Pacific Coast League","is_correct":false},{"id":"d","text":"Federal League","is_correct":false}],"explanation":"The National League dates to 1876; the American League declared itself a major league in 1901."},{"id":"q3","question":"Who won the first World Series, played in 1903?","options":[{"id":"a","text":"Boston Americans","is_correct":true},{"id":"b","text":"Chicago Cubs","is_correct":false},{"id":"c","text":"New York Giants","is_correct":false},{"id":"d","text":"Pittsburgh Pirates","is_correct":false}],"explanation":"The Boston Americans, later renamed the Red Sox, beat the Pittsburgh Pirates five games to three."},{"id":"q4","question":"Who holds the career home run record with 762?","options":[{"id":"a","text":"Barry Bonds","is_correct":true},{"id":"b","text":"Hank Aaron","is_correct":false},{"id":"c","text":"Babe Ruth","is_correct":false},{"id":"d","text":"Mark McGwire","is_correct":false}],"explanation":"Bonds passed Hank Aaron''s 755 in 2007 and finished his career with 762 home runs."},{"id":"q5","question":"Who is Major League Baseball''s all-time hits leader, with 4,256?","options":[{"id":"a","text":"Pete Rose","is_correct":true},{"id":"b","text":"Ty Cobb","is_correct":false},{"id":"c","text":"Derek Jeter","is_correct":false},{"id":"d","text":"Hank Aaron","is_correct":false}],"explanation":"Rose surpassed Ty Cobb in 1985; his 4,256 hits remain untouchable."},{"id":"q6","question":"The ''Curse of the Bambino'' supposedly began when Boston sold which player to the Yankees?","options":[{"id":"a","text":"Babe Ruth","is_correct":true},{"id":"b","text":"Lou Gehrig","is_correct":false},{"id":"c","text":"Ted Williams","is_correct":false},{"id":"d","text":"Cy Young","is_correct":false}],"explanation":"Boston sold Ruth after the 1919 season and did not win another World Series until 2004."},{"id":"q7","question":"Jackie Robinson broke baseball''s color barrier in 1947 playing for which team?","options":[{"id":"a","text":"Brooklyn Dodgers","is_correct":true},{"id":"b","text":"New York Yankees","is_correct":false},{"id":"c","text":"Boston Braves","is_correct":false},{"id":"d","text":"Cleveland Indians","is_correct":false}],"explanation":"Robinson debuted for Brooklyn on 15 April 1947; MLB retired his number 42 across the whole league."},{"id":"q8","question":"How far apart are the bases on a Major League diamond?","options":[{"id":"a","text":"90 feet","is_correct":true},{"id":"b","text":"60 feet","is_correct":false},{"id":"c","text":"100 feet","is_correct":false},{"id":"d","text":"75 feet","is_correct":false}],"explanation":"The 90-foot basepaths have been the standard since the nineteenth century; the mound sits 60 feet 6 inches from home."}]'::jsonb,
  null,
  array['mlb', 'baseball', 'sports history', 'records']::text[],
  3,
  'published',
