  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Which franchise has won the most World Series titles, with 27?","options":[{"id":"a","text":"New York Yankees","is_correct":true},{"id":"b","text":"St. Louis Cardinals","is_correct":false},{"id":"c","text":"Boston Red Sox","is_correct":false},{"id":"d","text":"San Francisco Giants","is_correct":false}],"explanation":"The Yankees'' 27 championships are far ahead of the Cardinals'' 11, the next best."},{"id":"q2","question":"Who pitched the only perfect game in World Series history, in 1956?","options":[{"id":"a","text":"Don Larsen","is_correct":true},{"id":"b","text":"Sandy Koufax","is_correct":false},{"id":"c","text":"Bob Gibson","is_correct":false},{"id":"d","text":"Whitey Ford","is_correct":false}],"explanation":"Larsen''s gem came in Game 5 for the Yankees against the Brooklyn Dodgers: 27 batters up, 27 down."},{"id":"q3","question":"Which slugger earned the nickname ''Mr. October'' for his World Series heroics?","options":[{"id":"a","text":"Reggie Jackson","is_correct":true},{"id":"b","text":"Babe Ruth","is_correct":false},{"id":"c","text":"Mickey Mantle","is_correct":false},{"id":"d","text":"Derek Jeter","is_correct":false}],"explanation":"Jackson hit three home runs in Game 6 of the 1977 Series for the Yankees — and ''Mr. October'' stuck."},{"id":"q4","question":"In 2016, the Cubs won their first World Series since what year?","options":[{"id":"a","text":"1908","is_correct":true},{"id":"b","text":"1945","is_correct":false},{"id":"c","text":"1918","is_correct":false},{"id":"d","text":"1929","is_correct":false}],"explanation":"The Cubs ended a 108-year drought, beating Cleveland in a dramatic Game 7."},{"id":"q5","question":"The 1969 ''Miracle Mets'' won the World Series by beating which heavily favored team?","options":[{"id":"a","text":"Baltimore Orioles","is_correct":true},{"id":"b","text":"New York Yankees","is_correct":false},{"id":"c","text":"Boston Red Sox","is_correct":false},{"id":"d","text":"Cincinnati Reds","is_correct":false}],"explanation":"The Mets, an expansion team only eight years old, beat the Orioles in five games."},{"id":"q6","question":"Who hit the only walk-off home run to end a World Series Game 7, in 1960?","options":[{"id":"a","text":"Bill Mazeroski","is_correct":true},{"id":"b","text":"Joe Carter","is_correct":false},{"id":"c","text":"Kirk Gibson","is_correct":false},{"id":"d","text":"Bobby Thomson","is_correct":false}],"explanation":"Mazeroski''s homer gave Pittsburgh the title over the Yankees; Joe Carter''s 1993 blast ended a Game 6."},{"id":"q7","question":"The 1989 World Series was interrupted by an earthquake during which matchup?","options":[{"id":"a","text":"Giants vs. Athletics","is_correct":true},{"id":"b","text":"Dodgers vs. Athletics","is_correct":false},{"id":"c","text":"Giants vs. Dodgers","is_correct":false},{"id":"d","text":"Athletics vs. Reds","is_correct":false}],"explanation":"The Loma Prieta earthquake struck before Game 3 in San Francisco; Oakland swept the Series."},{"id":"q8","question":"Who won the first World Series MVP award, in 1955?","options":[{"id":"a","text":"Johnny Podres","is_correct":true},{"id":"b","text":"Yogi Berra","is_correct":false},{"id":"c","text":"Duke Snider","is_correct":false},{"id":"d","text":"Sandy Koufax","is_correct":false}],"explanation":"Brooklyn left-hander Podres won two games, including the clincher, in the Dodgers'' first title."}]'::jsonb,
