values (
  'es-trivia-serie-mundial',
  'Trivia de la Serie Mundial: leyendas y momentos',
  'Ocho preguntas sobre la Serie Mundial: la dinastía de los Yankees, el único juego perfecto, sequías de un siglo, héroes de finales y el primer MVP.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿Qué franquicia ha ganado más Series Mundiales, con 27 títulos?","options":[{"id":"a","text":"New York Yankees","is_correct":true},{"id":"b","text":"St. Louis Cardinals","is_correct":false},{"id":"c","text":"Boston Red Sox","is_correct":false},{"id":"d","text":"San Francisco Giants","is_correct":false}],"explanation":"Los 27 campeonatos de los Yankees superan con creces los 11 de los Cardinals, segundos en la lista."},{"id":"q2","question":"¿Quién lanzó el único juego perfecto en la historia de la Serie Mundial, en 1956?","options":[{"id":"a","text":"Don Larsen","is_correct":true},{"id":"b","text":"Sandy Koufax","is_correct":false},{"id":"c","text":"Bob Gibson","is_correct":false},{"id":"d","text":"Whitey Ford","is_correct":false}],"explanation":"La joya de Larsen fue en el Juego 5, con los Yankees ante los Brooklyn Dodgers: 27 bateadores, 27 outs."},{"id":"q3","question":"¿Qué bateador se ganó el apodo de ''Mr. October'' por sus hazañas en la Serie Mundial?","options":[{"id":"a","text":"Reggie Jackson","is_correct":true},{"id":"b","text":"Babe Ruth","is_correct":false},{"id":"c","text":"Mickey Mantle","is_correct":false},{"id":"d","text":"Derek Jeter","is_correct":false}],"explanation":"Jackson conectó tres jonrones en el Juego 6 de la Serie de 1977 con los Yankees y el apodo se quedó."},{"id":"q4","question":"En 2016, los Cubs ganaron su primera Serie Mundial desde qué año?","options":[{"id":"a","text":"1908","is_correct":true},{"id":"b","text":"1945","is_correct":false},{"id":"c","text":"1918","is_correct":false},{"id":"d","text":"1929","is_correct":false}],"explanation":"Los Cubs acabaron con una sequía de 108 años al vencer a Cleveland en un dramático Juego 7."},{"id":"q5","question":"Los ''Miracle Mets'' de 1969 ganaron la Serie Mundial al vencer a qué equipo muy favorito?","options":[{"id":"a","text":"Baltimore Orioles","is_correct":true},{"id":"b","text":"New York Yankees","is_correct":false},{"id":"c","text":"Boston Red Sox","is_correct":false},{"id":"d","text":"Cincinnati Reds","is_correct":false}],"explanation":"Los Mets, un equipo de expansión de apenas ocho años, vencieron a los Orioles en cinco juegos."},{"id":"q6","question":"¿Quién conectó el único cuadrangular que terminó un Juego 7 de Serie Mundial, en 1960?","options":[{"id":"a","text":"Bill Mazeroski","is_correct":true},{"id":"b","text":"Joe Carter","is_correct":false},{"id":"c","text":"Kirk Gibson","is_correct":false},{"id":"d","text":"Bobby Thomson","is_correct":false}],"explanation":"El jonrón de Mazeroski le dio el título a Pittsburgh sobre los Yankees; el de Joe Carter en 1993 cerró un Juego 6."},{"id":"q7","question":"La Serie Mundial de 1989 se interrumpió por un terremoto durante qué cruce?","options":[{"id":"a","text":"Giants contra Athletics","is_correct":true},{"id":"b","text":"Dodgers contra Athletics","is_correct":false},{"id":"c","text":"Giants contra Dodgers","is_correct":false},{"id":"d","text":"Athletics contra Reds","is_correct":false}],"explanation":"El terremoto de Loma Prieta sacudió San Francisco antes del Juego 3; Oakland barrió la Serie."},{"id":"q8","question":"¿Quién ganó el primer premio MVP de la Serie Mundial, en 1955?","options":[{"id":"a","text":"Johnny Podres","is_correct":true},{"id":"b","text":"Yogi Berra","is_correct":false},{"id":"c","text":"Duke Snider","is_correct":false},{"id":"d","text":"Sandy Koufax","is_correct":false}],"explanation":"El zurdo Podres ganó dos juegos, incluido el del título, en el primer campeonato de los Dodgers."}]'::jsonb,
