insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-caribbean-series-trivia',
  'Caribbean Series Trivia: Latin Baseball''s Crown',
  'Eight questions on the Caribbean Series and Latin baseball: the 1949 debut in Havana, dominant clubs and the Latino legends who reached the Hall of Fame.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"In which city was the first Caribbean Series played, in 1949?","options":[{"id":"a","text":"Havana","is_correct":true},{"id":"b","text":"San Juan","is_correct":false},{"id":"c","text":"Caracas","is_correct":false},{"id":"d","text":"Santo Domingo","is_correct":false}],"explanation":"Cuba hosted the inaugural Serie del Caribe in February 1949 at Havana''s Gran Estadio."},{"id":"q2","question":"Which club won that inaugural Caribbean Series in 1949?","options":[{"id":"a","text":"Almendares","is_correct":true},{"id":"b","text":"Cangrejeros de Santurce","is_correct":false},{"id":"c","text":"Tigres del Licey","is_correct":false},{"id":"d","text":"Navegantes del Magallanes","is_correct":false}],"explanation":"Cuba''s Almendares went unbeaten to take the first title; the other three clubs became Caribbean powers later."},{"id":"q3","question":"Which country''s clubs have won the most Caribbean Series titles?","options":[{"id":"a","text":"Dominican Republic","is_correct":true},{"id":"b","text":"Puerto Rico","is_correct":false},{"id":"c","text":"Venezuela","is_correct":false},{"id":"d","text":"Mexico","is_correct":false}],"explanation":"Dominican clubs, led by Licey and Águilas Cibaeñas, top the all-time table ahead of Puerto Rico."},{"id":"q4","question":"Which club has won the most Caribbean Series championships?","options":[{"id":"a","text":"Tigres del Licey","is_correct":true},{"id":"b","text":"Águilas Cibaeñas","is_correct":false},{"id":"c","text":"Criollos de Caguas","is_correct":false},{"id":"d","text":"Leones del Caracas","is_correct":false}],"explanation":"Santo Domingo''s Tigres del Licey hold the record for Caribbean crowns."},{"id":"q5","question":"Which country joined the Caribbean Series in 1971, after the tournament''s revival?","options":[{"id":"a","text":"Mexico","is_correct":true},{"id":"b","text":"Cuba","is_correct":false},{"id":"c","text":"Panama","is_correct":false},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"Cuba left after 1960 and the tournament paused for a decade; when it returned, Mexico''s Pacific League joined in 1971."},{"id":"q6","question":"Who was the first Latin American-born player inducted into the National Baseball Hall of Fame?","options":[{"id":"a","text":"Roberto Clemente","is_correct":true},{"id":"b","text":"Juan Marichal","is_correct":false},{"id":"c","text":"Orlando Cepeda","is_correct":false},{"id":"d","text":"Luis Aparicio","is_correct":false}],"explanation":"Puerto Rico''s Clemente was elected in a special 1973 vote after his death; Marichal, Cepeda and Aparicio followed."},{"id":"q7","question":"Who was the first Dominican-born player elected to the Hall of Fame?","options":[{"id":"a","text":"Juan Marichal","is_correct":true},{"id":"b","text":"Pedro Martínez","is_correct":false},{"id":"c","text":"Sammy Sosa","is_correct":false},{"id":"d","text":"Vladimir Guerrero","is_correct":false}],"explanation":"Marichal, the ''Dominican Dandy'' with the high leg kick, was inducted in 1983; Pedro Martínez followed in 2015."},{"id":"q8","question":"In 1981, which Mexican pitcher won both Rookie of the Year and the Cy Young Award?","options":[{"id":"a","text":"Fernando Valenzuela","is_correct":true},{"id":"b","text":"Jaime García","is_correct":false},{"id":"c","text":"Yovani Gallardo","is_correct":false},{"id":"d","text":"Teddy Higuera","is_correct":false}],"explanation":"''Fernandomania'' swept baseball in 1981; no rookie has matched Valenzuela''s double since."}]'::jsonb,
  null,
  array['caribbean series', 'baseball', 'latin america', 'hall of fame']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

