values (
  'es-trivia-serie-del-caribe',
  'Trivia de la Serie del Caribe: la corona del béisbol latino',
  'Ocho preguntas sobre la Serie del Caribe y el béisbol latino: el debut de 1949 en La Habana, los clubes dominantes y las leyendas del Salón de la Fama.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿En qué ciudad se jugó la primera Serie del Caribe, en 1949?","options":[{"id":"a","text":"La Habana","is_correct":true},{"id":"b","text":"San Juan","is_correct":false},{"id":"c","text":"Caracas","is_correct":false},{"id":"d","text":"Santo Domingo","is_correct":false}],"explanation":"Cuba fue sede de la Serie del Caribe inaugural en febrero de 1949, en el Gran Estadio de La Habana."},{"id":"q2","question":"¿Qué club ganó esa Serie del Caribe inaugural de 1949?","options":[{"id":"a","text":"Almendares","is_correct":true},{"id":"b","text":"Cangrejeros de Santurce","is_correct":false},{"id":"c","text":"Tigres del Licey","is_correct":false},{"id":"d","text":"Navegantes del Magallanes","is_correct":false}],"explanation":"El Almendares de Cuba se coronó invicto; los otros tres clubes se volvieron potencias caribeñas después."},{"id":"q3","question":"¿De qué país son los clubes con más títulos de la Serie del Caribe?","options":[{"id":"a","text":"República Dominicana","is_correct":true},{"id":"b","text":"Puerto Rico","is_correct":false},{"id":"c","text":"Venezuela","is_correct":false},{"id":"d","text":"México","is_correct":false}],"explanation":"Los clubes dominicanos, liderados por Licey y Águilas Cibaeñas, encabezan la tabla histórica por delante de Puerto Rico."},{"id":"q4","question":"¿Qué club ha ganado más campeonatos de la Serie del Caribe?","options":[{"id":"a","text":"Tigres del Licey","is_correct":true},{"id":"b","text":"Águilas Cibaeñas","is_correct":false},{"id":"c","text":"Criollos de Caguas","is_correct":false},{"id":"d","text":"Leones del Caracas","is_correct":false}],"explanation":"Los Tigres del Licey de Santo Domingo tienen el récord de coronas caribeñas."},{"id":"q5","question":"¿Qué país se incorporó a la Serie del Caribe en 1971, tras el regreso del torneo?","options":[{"id":"a","text":"México","is_correct":true},{"id":"b","text":"Cuba","is_correct":false},{"id":"c","text":"Panamá","is_correct":false},{"id":"d","text":"Colombia","is_correct":false}],"explanation":"Cuba salió después de 1960 y el torneo se detuvo una década; al volver, la Liga Mexicana del Pacífico se sumó en 1971."},{"id":"q6","question":"¿Quién fue el primer jugador nacido en América Latina en entrar al Salón de la Fama del Béisbol?","options":[{"id":"a","text":"Roberto Clemente","is_correct":true},{"id":"b","text":"Juan Marichal","is_correct":false},{"id":"c","text":"Orlando Cepeda","is_correct":false},{"id":"d","text":"Luis Aparicio","is_correct":false}],"explanation":"El puertorriqueño Clemente fue elegido en una votación especial de 1973 tras su muerte; Marichal, Cepeda y Aparicio llegaron después."},{"id":"q7","question":"¿Quién fue el primer jugador nacido en República Dominicana elegido al Salón de la Fama?","options":[{"id":"a","text":"Juan Marichal","is_correct":true},{"id":"b","text":"Pedro Martínez","is_correct":false},{"id":"c","text":"Sammy Sosa","is_correct":false},{"id":"d","text":"Vladimir Guerrero","is_correct":false}],"explanation":"Marichal, el ''Dandy Dominicano'' de la pierna en alto, entró en 1983; Pedro Martínez lo siguió en 2015."},{"id":"q8","question":"En 1981, ¿qué lanzador mexicano ganó el Novato del Año y el Premio Cy Young?","options":[{"id":"a","text":"Fernando Valenzuela","is_correct":true},{"id":"b","text":"Jaime García","is_correct":false},{"id":"c","text":"Yovani Gallardo","is_correct":false},{"id":"d","text":"Teddy Higuera","is_correct":false}],"explanation":"La ''Fernandomanía'' arrasó el béisbol en 1981; ningún novato ha igualado desde entonces ese doblete de Valenzuela."}]'::jsonb,
